-- Kiểm tra: số event 4 bước phễu theo ngày, toàn bộ giai đoạn.
-- Kết quả: add_to_cart gần như = 0 từ 01/11 đến 25/11/2020 trong khi purchase vẫn có
--          → thiếu tracking, mart_funnel chỉ dùng dữ liệu từ 26/11/2020.
SELECT
  PARSE_DATE('%Y%m%d', _TABLE_SUFFIX) AS event_day,
  COUNTIF(event_name = 'view_item')      AS view_item,
  COUNTIF(event_name = 'add_to_cart')    AS add_to_cart,
  COUNTIF(event_name = 'begin_checkout') AS begin_checkout,
  COUNTIF(event_name = 'purchase')       AS purchase
FROM `bigquery-public-data.ga4_obfuscated_sample_ecommerce.events_*`
WHERE _TABLE_SUFFIX BETWEEN '20201101' AND '20210131'
GROUP BY event_day
ORDER BY event_day;


